	assert.match(xs, /lbp_callback_invoke\(\(lbp_callback \*\)context, &frame\)/u);
	assert.match(xs, new RegExp(`\\nvisit\\(\\.\\.\\.\\)[\\s\\S]+${visit.symbol}\\(`, "u"));
